function lang(){return data?.settings?.language==='zh'?'zh':'ja'}
function t(key,vars={}){let value=(I18N[lang()]&&I18N[lang()][key])||I18N.ja[key]||key;Object.entries(vars).forEach(([k,v])=>value=value.replaceAll(`{${k}}`,v));return value}
function trText(value){return lang()==='zh'?(TEXT_ZH[value]||value):value}
function setText(sel,key,vars={}){const el=document.querySelector(sel);if(el)el.textContent=t(key,vars)}
function syncMessage(message){if(lang()==='zh')return message;return {'登录后自动同步':'ログイン後に自動同期します','未配置 Supabase':'Supabase が未設定です','网络恢复，正在同步':'ネットワーク復帰、同期中です','离线可用，联网后同步':'オフラインで利用できます。接続後に同期します','同步初始化失败':'同期の初期化に失敗しました','已退出，仅保留本地数据':'ログアウトしました。本機データは残ります','点击邮件链接完成登录':'メール内のリンクでログインを完了してください','请先完成邮箱确认':'先にメール確認を完了してください','密码已更新，手机可用密码登录':'パスワードを更新しました。スマホでもログインできます','云端与本机一致':'クラウドと本機は一致しています','正在检查云端数据':'クラウドデータを確認しています','已载入云端数据':'クラウドデータを読み込みました','云端暂不可用，稍后自动重试':'クラウドに接続できません。後で自動再試行します','已载入另一台设备的新数据':'別端末の新しいデータを読み込みました','本机已保存，稍后自动同步':'本機に保存しました。後で自動同期します','本机已保存，准备上传':'本機に保存しました。アップロード準備中です'}[message]||message}

function blankData(){return{
  schemaVersion:4,updated_at:new Date().toISOString(),
  settings:{newWordsGoal:10,reviewWordsGoal:10,weekdayCap:70,language:'ja'},
  lesson:{number:1,checks:Object.fromEntries(lessonParts.map(x=>[x,false])),progressUpdatedAt:null},
  tasks:{},weekPlans:{},logs:{words:{},listening:{},tests:{},practice:{}},practiceTimer:null,vocab:defaultVocab,calendarMonth:null
}}
function normalizeData(raw={}){const base=blankData(), merged={...base,...raw};merged.settings={...base.settings,...(raw.settings||{})};merged.lesson={...base.lesson,...(raw.lesson||{})};merged.lesson.checks=normalizeLessonChecks((raw.lesson||{}).checks||{});merged.logs={words:{},listening:{},tests:{},...(raw.logs||{})};merged.logs.words=merged.logs.words||{};merged.logs.listening=merged.logs.listening||{};merged.logs.tests=merged.logs.tests||{};merged.logs.practice=merged.logs.practice||{};merged.practiceTimer=raw.practiceTimer&&raw.practiceTimer.startedAt?raw.practiceTimer:null;merged.tasks=merged.tasks||{};merged.weekPlans=merged.weekPlans||{};merged.vocab=Array.isArray(merged.vocab)?merged.vocab:base.vocab;merged.schemaVersion=4;merged.updated_at=raw.updated_at||raw.updatedAt||base.updated_at;return merged}
let data=load();
function load(){try{return normalizeData(JSON.parse(localStorage.getItem(KEY)||'{}'))}catch{return blankData()}}
function save(options={}){data.updated_at=new Date().toISOString();localStorage.setItem(KEY,JSON.stringify(data));if(sync&&!options.skipSync)sync.queuePush()}
function replaceData(next,options={}){data=normalizeData(next);localStorage.setItem(KEY,JSON.stringify(data));if(!options.skipRender)render()}
function todayKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function parseKey(k){const [y,m,d]=k.split('-').map(Number);return new Date(y,m-1,d)}
function isWeekend(d=new Date()){return d.getDay()===0||d.getDay()===6}
function weekdayCN(d=new Date()){return '日一二三四五六'[d.getDay()]}
function minutesForType(type){return ({教材:20,语法:20,教材听力:15,课外听力:15,跟读:10,复习:10,口语:25,测试:20,单词:10,教科書:20,文法:20,リスニング:15,シャドーイング:10,復習:10,会話:25,テスト:20,単語:10})[type]||10}
function task(id,title,type,meta='',scheduledDay=null){return{id,title,type,meta,done:false,created:todayKey(),carried:false,scheduledDay}}
function normalizeLessonChecks(checks={}){const aliases={'单词':'単語','语法①':'文法①','语法②':'文法②','课文':'本文','课文听力':'本文リスニング','跟读':'音読'};const next=Object.fromEntries(lessonParts.map(x=>[x,false]));Object.entries(checks).forEach(([k,v])=>{const key=aliases[k]||k;if(key in next)next[key]=Boolean(v)});return next}
function weekStart(d=new Date()){const x=new Date(d);const shift=(x.getDay()+6)%7;x.setHours(0,0,0,0);x.setDate(x.getDate()-shift);return x}
function weekId(d=new Date()){return todayKey(weekStart(d))}
function dayIndex(d=new Date()){return (d.getDay()+6)%7}

function loadSyncMeta(){try{return JSON.parse(localStorage.getItem(SYNC_META_KEY)||'{}')}catch{return {}}}
function saveSyncMeta(meta){localStorage.setItem(SYNC_META_KEY,JSON.stringify(meta))}
function dataScore(value=data){const x=normalizeData(value);return Object.keys(x.tasks||{}).length*4+Object.keys(x.weekPlans||{}).length*4+Object.keys(x.logs.words||{}).length*3+Object.keys(x.logs.listening||{}).length*3+Object.keys(x.logs.tests||{}).length*3+Math.max(0,(x.vocab||[]).length-defaultVocab.length)*2+(x.lesson?.number&&x.lesson.number!==1?3:0)+Object.values(x.lesson?.checks||{}).filter(Boolean).length}
function hasMeaningfulLocalData(value=data){return dataScore(value)>0}
function makeLocalBackup(reason='sync'){const snapshot=normalizeData(data);if(!hasMeaningfulLocalData(snapshot))return null;const key=`${PRE_SYNC_BACKUP_PREFIX}${Date.now()}-${reason}`;localStorage.setItem(key,JSON.stringify({...snapshot,backup_reason:reason,backup_created_at:new Date().toISOString()}));return key}
function listLocalBackups(){const rows=[];for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(!key||!key.startsWith(PRE_SYNC_BACKUP_PREFIX))continue;try{const value=normalizeData(JSON.parse(localStorage.getItem(key)||'{}'));rows.push({key,value,score:dataScore(value),time:value.backup_created_at||value.updated_at||''})}catch{}}return rows.sort((a,b)=>String(b.time).localeCompare(String(a.time)))}
function compareUpdated(a,b){return new Date(a||0).getTime()-new Date(b||0).getTime()}
function resolveLessonProgress(localLesson={},remoteLesson={}){
 const normalize=lesson=>({number:Math.max(1,Number(lesson.number)||1),checks:normalizeLessonChecks(lesson.checks||{}),progressUpdatedAt:lesson.progressUpdatedAt||null});
 const local=normalize(localLesson),remote=normalize(remoteLesson),lt=Date.parse(local.progressUpdatedAt||0)||0,rt=Date.parse(remote.progressUpdatedAt||0)||0;
 if(lt&&rt&&lt!==rt)return lt>rt?local:remote;
 if(local.number!==remote.number)return local.number>remote.number?local:remote;
 if(lt!==rt)return lt>rt?local:remote;
 const count=lesson=>lessonParts.filter(p=>lesson.checks[p]).length;
 return count(local)>=count(remote)?local:remote;
}
function createSync(){
 const cfg=window.JP_STUDY_SUPABASE||{};
 const available=Boolean(cfg.url&&cfg.anonKey&&window.supabase);
 const state={available,client:null,user:null,status:available?'未登录':'本地',message:available?'登录后自动同步':'未配置 Supabase',timer:null,poller:null,busy:false,lastSync:null,error:null};
 if(available)state.client=window.supabase.createClient(cfg.url,cfg.anonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,storageKey:'jp-study-supabase-auth'}});
 function setStatus(status,message,error=null){state.status=status;state.message=message;state.error=error;renderSyncStatus()}
 function startAutoSync(){stopAutoSync();state.poller=setInterval(()=>pullThenPush(),20000)}
 function stopAutoSync(){if(state.poller){clearInterval(state.poller);state.poller=null}}
 async function init(){renderSyncStatus();window.addEventListener('online',()=>{if(state.user){setStatus('同步中','网络恢复，正在同步');pullThenPush()}});window.addEventListener('offline',()=>setStatus('离线','离线可用，联网后同步'));window.addEventListener('focus',()=>{if(state.user)pullThenPush()});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.user)pullThenPush()});
  if(!state.available)return;
  try{const {data:sessionData}=await state.client.auth.getSession();state.user=sessionData.session?.user||null;if(state.user){startAutoSync();await firstSync()}else setStatus('未登录','登录后自动同步')}catch(err){setStatus('异常','同步初始化失败',err)}
  state.client.auth.onAuthStateChange((_event,session)=>{state.user=session?.user||null;if(state.user){startAutoSync();firstSync()}else{stopAutoSync();setStatus('未登录','已退出，仅保留本地数据')}});
 }
 async function signIn(email){if(!state.available)throw new Error('请先填写 Supabase 配置。');const redirectTo=location.href.split('#')[0];const {error}=await state.client.auth.signInWithOtp({email,options:{emailRedirectTo:redirectTo}});if(error)throw error;setStatus('查收邮件','点击邮件链接完成登录')}
 async function signInPassword(email,password){if(!state.available)throw new Error('请先填写 Supabase 配置。');const {data:auth,error}=await state.client.auth.signInWithPassword({email,password});if(error)throw error;state.user=auth.session?.user||auth.user;startAutoSync();await firstSync()}
 async function signUpPassword(email,password){if(!state.available)throw new Error('请先填写 Supabase 配置。');const {data:auth,error}=await state.client.auth.signUp({email,password});if(error)throw error;if(auth.session?.user){state.user=auth.session.user;startAutoSync();await firstSync()}else setStatus('查收邮件','请先完成邮箱确认')}
 async function updatePassword(password){if(!state.available||!state.user)throw new Error('请先登录。');const {error}=await state.client.auth.updateUser({password});if(error)throw error;setStatus('已同步','密码已更新，手机可用密码登录')}
 async function signOut(){if(!state.available)return;await state.client.auth.signOut();state.user=null;setStatus('未登录','已退出，仅保留本地数据')}
 async function fetchRemote(){const {data:row,error}=await state.client.from('study_states').select('data,updated_at').eq('user_id',state.user.id).maybeSingle();if(error)throw error;return row}
 async function upsertRemote(payload=data){const stamped=normalizeData(payload);const {error}=await state.client.from('study_states').upsert({user_id:state.user.id,data:stamped,updated_at:stamped.updated_at},{onConflict:'user_id'});if(error)throw error;state.lastSync=new Date().toISOString();const meta=loadSyncMeta();meta.pending=false;meta.lastSync=state.lastSync;saveSyncMeta(meta);setStatus('已同步','云端与本机一致')}
 async function firstSync(){if(state.busy)return;state.busy=true;try{if(!navigator.onLine){setStatus('离线','离线可用，联网后同步');return}setStatus('同步中','正在检查云端数据');const remote=await fetchRemote();const meta=loadSyncMeta();const migrated=meta.migratedUsers?.[state.user.id];
   if(!remote){makeLocalBackup('before-first-cloud-upload');await upsertRemote(data);meta.migratedUsers={...(meta.migratedUsers||{}),[state.user.id]:true};saveSyncMeta(meta);return}
   const remoteData=normalizeData(remote.data),remoteLessonBefore=JSON.stringify(remoteData.lesson),resolvedLesson=resolveLessonProgress(data.lesson,remoteData.lesson),lessonNeedsUpload=JSON.stringify(resolvedLesson)!==remoteLessonBefore;data.lesson=resolvedLesson;remoteData.lesson=resolvedLesson;const localScore=dataScore(data), remoteScore=dataScore(remoteData), localIsNewer=compareUpdated(data.updated_at,remote.updated_at)>0;
   if(!migrated&&hasMeaningfulLocalData())makeLocalBackup('before-first-sync');
   if(!migrated&&hasMeaningfulLocalData()&&(localScore>remoteScore+2||(localIsNewer&&localScore>=remoteScore))){await upsertRemote(data);meta.migratedUsers={...(meta.migratedUsers||{}),[state.user.id]:true};saveSyncMeta(meta);return}
   replaceData(remoteData,{skipRender:true});if(lessonNeedsUpload){await upsertRemote(data);render();return}state.lastSync=new Date().toISOString();meta.pending=false;meta.lastSync=state.lastSync;meta.migratedUsers={...(meta.migratedUsers||{}),[state.user.id]:true};saveSyncMeta(meta);setStatus('已同步','已载入云端数据');render()
  }catch(err){const meta=loadSyncMeta();meta.pending=true;saveSyncMeta(meta);setStatus('待同步','云端暂不可用，稍后自动重试',err)}finally{state.busy=false}}
 async function pullThenPush(){if(!state.available||!state.user||state.busy)return;state.busy=true;try{if(!navigator.onLine){setStatus('离线','离线可用，联网后同步');return}const remote=await fetchRemote(),meta=loadSyncMeta(),pending=Boolean(meta.pending);if(!remote){await upsertRemote(data);return}const remoteData=normalizeData(remote.data),remoteLessonBefore=JSON.stringify(remoteData.lesson),resolvedLesson=resolveLessonProgress(data.lesson,remoteData.lesson),lessonNeedsUpload=JSON.stringify(resolvedLesson)!==remoteLessonBefore;data.lesson=resolvedLesson;remoteData.lesson=resolvedLesson;const localScore=dataScore(data),remoteScore=dataScore(remoteData),remoteIsNewer=compareUpdated(remote.updated_at,data.updated_at)>0,localIsNewer=compareUpdated(data.updated_at,remote.updated_at)>0;if(remoteIsNewer||(!pending&&remoteScore>localScore+2)||(pending&&localIsNewer&&localScore+2<remoteScore)){makeLocalBackup('before-cloud-replace');replaceData(remoteData,{skipRender:true});if(lessonNeedsUpload){await upsertRemote(data);render();return}meta.pending=false;saveSyncMeta(meta);setStatus('已同步','已载入另一台设备的新数据');render();return}if(pending||localIsNewer||lessonNeedsUpload){await upsertRemote(data);return}meta.pending=false;saveSyncMeta(meta);setStatus('已同步','云端与本机一致')}catch(err){const meta=loadSyncMeta();meta.pending=true;saveSyncMeta(meta);setStatus('待同步','本机已保存，稍后自动同步',err)}finally{state.busy=false}}
 function queuePush(){const meta=loadSyncMeta();meta.pending=true;saveSyncMeta(meta);if(!state.available||!state.user){renderSyncStatus();return}if(!navigator.onLine){setStatus('离线','离线可用，联网后同步');return}setStatus('待同步','本机已保存，准备上传');clearTimeout(state.timer);state.timer=setTimeout(()=>pullThenPush(),700)}
 return {state,init,signIn,signInPassword,signUpPassword,updatePassword,signOut,queuePush,pullThenPush};
}

function weeklyTemplate(startKey){
 const days=['月','火','水','木','金','土','日'];
 const rows=[
  ['textStudy','本文の精読とディクテーション','教科書','本文を精読し、1段落を聞き取り、原文と照合して訂正する',0],
  ['newVocab','新出語の学習','単語','新出語10〜15語：読み・意味・例文を確認する',1],
  ['grammarPractice','文法と練習','文法','文法1〜2項目を学び、教科書問題と自作文3つを行う',2],
  ['vocabDictation','単語整理とディクテーション','単語','今週の単語を整理し、漢字・仮名・意味を聞き取って書く',3],
  ['extraListening','課外リスニングとシャドーイング','リスニング','課外素材を15〜20分聞き、3〜5文を繰り返して音読する',4]
 ];
 return {id:startKey,created:todayKey(),templateVersion:2,tasks:rows.map(([id,title,type,meta,scheduledDay])=>({id:`${startKey}-${id}`,title,type,meta,scheduledDay,dayName:days[scheduledDay],done:false,created:startKey}))};
}
function ensureToday(){ensureWeek()}
function ensureWeek(d=new Date()){
 const id=weekId(d);
 data.weekPlans=data.weekPlans||{};
 const existing=data.weekPlans[id];
 if(existing&&existing.templateVersion===2)return existing;
 if(existing){
   const custom=(existing.tasks||[]).filter(t=>String(t.id||'').startsWith('custom-'));
   const refreshed=weeklyTemplate(id);refreshed.tasks.push(...custom);data.weekPlans[id]=refreshed;save();return refreshed;
 }
 data.weekPlans[id]=weeklyTemplate(id);
 save();
 return data.weekPlans[id];
}
function currentWeekTasks(){return ensureWeek().tasks||[]}
function recommendedTasks(){const idx=dayIndex();return currentWeekTasks().filter(t=>t.scheduledDay<=idx&&!t.done)}
function tasksForDateKey(k){const d=parseKey(k), plan=data.weekPlans?.[weekId(d)];if(plan)return (plan.tasks||[]).filter(t=>t.scheduledDay===dayIndex(d));return data.tasks[k]||[]}

function render(){ensureToday();applyStaticTexts();renderHeader();renderPracticeTimer();renderTasks();renderLesson();renderWords();renderWeekend();renderCalendar();renderSummary();renderSyncStatus()}
function applyStaticTexts(){
 document.documentElement.lang=lang()==='zh'?'zh-CN':'ja';document.title=t('appTitle');
 setText('#appTitle','appTitle');setText('#todayTag','todayTag');setText('#heroTitle','heroTitle');setText('#heroSub','heroSub');setText('#practiceLabel','practiceLabel');setText('#langToggleBtn','langToggle');
 setText('#recommendedTitle','recommendedTitle');setText('#addTaskBtn','addTask');setText('#weekTitle','weekTitle');setText('#lessonTitle','lessonTitle');setText('#lessonPrefix','lessonPrefix');setText('#lessonSuffix','lessonSuffix');setText('#editLessonBtn','edit');setText('#vocabTitle','vocabTitle');setText('#newWordsLabel','newWords');setText('#reviewWordsLabel','review');setText('#logWordsBtn','record');setText('#vocabBtn','vocab');
 setText('#listeningTitle','listeningTitle');setText('#logListeningBtn','addRecord');setText('#weekendTag','weekendTag');setText('#weekendTitle','weekendTitle');setText('#weekendDesc','weekendDesc');setText('#startTestBtn','startTest');setText('#navToday','todayTag');setText('#navCalendar','calendar');setText('#quickTestBtn','test');setText('#backupBtn','backup');setText('#weekRateLabel','weekRate');setText('#masteredWordsLabel','masteredWords');
 const settingsBtn=document.querySelector('#settingsBtn');if(settingsBtn)settingsBtn.setAttribute('aria-label',t('settings'));
}
function renderHeader(){const d=new Date();const days=lang()==='zh'?['日','一','二','三','四','五','六']:['日','月','火','水','木','金','土'];document.querySelector('#todayLabel').textContent=lang()==='zh'?`${d.getMonth()+1}月${d.getDate()}日 · 周${days[d.getDay()]}`:`${d.getMonth()+1}月${d.getDate()}日 · ${days[d.getDay()]}曜日`}
function formatDuration(seconds){const s=Math.max(0,Math.floor(seconds));const h=String(Math.floor(s/3600)).padStart(2,'0'),m=String(Math.floor(s%3600/60)).padStart(2,'0'),sec=String(s%60).padStart(2,'0');return `${h}:${m}:${sec}`}
function activePracticeSecondsForDate(key){const timer=data.practiceTimer;if(!timer?.startedAt)return 0;const start=Date.parse(timer.startedAt);if(!Number.isFinite(start))return 0;const dayStart=parseKey(key),dayEnd=new Date(dayStart);dayEnd.setDate(dayEnd.getDate()+1);return Math.max(0,Math.floor((Math.min(Date.now(),dayEnd.getTime())-Math.max(start,dayStart.getTime()))/1000))}
function practiceSecondsForDate(key){return Number(data.logs.practice?.[key]||0)+activePracticeSecondsForDate(key)}
function todayPracticeSeconds(){return practiceSecondsForDate(todayKey())}
function formatStudyShort(seconds){const min=Math.floor(seconds/60);if(seconds>0&&min===0)return '<1分';if(min<60)return `${min}分`;const h=Math.floor(min/60),m=min%60;return `${h}h${m?m+'m':''}`}
function formatStudyTotal(seconds){const min=Math.floor(seconds/60),h=Math.floor(min/60),m=min%60;if(lang()==='zh')return h?`${h}小时${m?m+'分钟':''}`:`${m}分钟`;return h?`${h}時間${m?m+'分':''}`:`${m}分`}
function sumPractice(prefix){return Object.entries(data.logs.practice||{}).reduce((sum,[key,value])=>sum+(key.startsWith(prefix)?Number(value||0):0),0)}
function updateCalendarPracticeDisplay(){const today=todayKey();document.querySelectorAll('[data-study-date]').forEach(el=>{const key=el.dataset.studyDate,seconds=practiceSecondsForDate(key);el.textContent=formatStudyShort(seconds);el.hidden=seconds<=0});const summary=document.querySelector('#calendarStudySummary');if(summary){const month=`${calDate.getFullYear()}-${String(calDate.getMonth()+1).padStart(2,'0')}`,year=String(calDate.getFullYear()),activeMonth=today.startsWith(month)?activePracticeSecondsForDate(today):0,activeYear=today.startsWith(year)?activePracticeSecondsForDate(today):0;summary.innerHTML=`<span>${t('monthStudied')} <strong>${formatStudyTotal(sumPractice(month)+activeMonth)}</strong></span><span>${t('yearStudied')} <strong>${formatStudyTotal(sumPractice(year)+activeYear)}</strong></span>`}}
function updatePracticeTimerDisplay(){const btn=document.querySelector('#practiceTimerBtn');if(!btn)return;const running=Boolean(data.practiceTimer?.startedAt);document.querySelector('#practiceTimerTime').textContent=formatDuration(todayPracticeSeconds());document.querySelector('#practiceTimerStatus').textContent=running?t('practiceStop'):t('practiceStart');btn.classList.toggle('running',running);btn.setAttribute('aria-pressed',String(running));updateCalendarPracticeDisplay()}
function renderPracticeTimer(){updatePracticeTimerDisplay();if(!practiceTicker)practiceTicker=setInterval(updatePracticeTimerDisplay,1000)}
function addPracticeSpan(start,end){data.logs.practice=data.logs.practice||{};let cursor=Math.max(0,start);while(cursor<end){const d=new Date(cursor),key=todayKey(d),next=new Date(d);next.setHours(24,0,0,0);const edge=Math.min(end,next.getTime());data.logs.practice[key]=Number(data.logs.practice[key]||0)+Math.max(0,Math.floor((edge-cursor)/1000));cursor=edge}}
function togglePracticeTimer(){const timer=data.practiceTimer;if(timer?.startedAt){const start=Date.parse(timer.startedAt);if(Number.isFinite(start))addPracticeSpan(start,Date.now());data.practiceTimer=null}else{data.practiceTimer={startedAt:new Date().toISOString()}}save();renderPracticeTimer();renderSyncStatus()}

function renderSyncStatus(){const btn=document.querySelector('#syncBtn');if(!btn||!sync)return;const s=sync.state;const meta=loadSyncMeta();const labels={'本地':t('statusLocal'),'未登录':t('statusLoggedOut'),'待同步':t('statusPending'),'已同步':t('statusSynced'),'离线':t('statusOffline'),'异常':t('statusError'),'同步中':t('statusSyncing'),'查收邮件':t('statusCheckEmail')};const text=s.user?(meta.pending&&s.status!=='已同步'?'待同步':s.status):s.status;btn.textContent=labels[text]||text;btn.className='sync-pill '+(s.user?'online':'')+(s.status==='离线'||meta.pending?' pending':'')+(s.error?' error':'')}
function renderTaskList(box,arr,emptyText,showDay=false){box.innerHTML='';if(!arr.length)box.innerHTML=`<div class="task-item empty">${emptyText}</div>`;arr.forEach(t=>{const el=document.createElement('label');el.className='task-item'+(t.done?' done':'')+(showDay?' weekly':'');el.innerHTML=`<input class="task-check" type="checkbox" ${t.done?'checked':''}><div class="task-body">${showDay?`<div class="task-day">${trText(t.dayName||'')}</div>`:''}<div class="task-title">${esc(trText(t.title))}</div><div class="task-meta">${esc(trText(t.type))}${t.meta?' · '+esc(trText(t.meta)):''}</div></div>`;el.querySelector('input').onchange=e=>{t.done=e.target.checked;save();render()};box.appendChild(el)})}
function renderTasks(){const weekBox=document.querySelector('#weekTaskList'),all=currentWeekTasks();renderTaskList(weekBox,all,t('emptyWeek'),true)}
function renderLesson(message=''){document.querySelector('#lessonNumber').textContent=data.lesson.number;const box=document.querySelector('#lessonChecks');box.innerHTML='';lessonParts.forEach(p=>{const l=document.createElement('label');l.className='mini-check';l.innerHTML=`<input type="checkbox" ${data.lesson.checks[p]?'checked':''}> ${trText(p)}`;l.querySelector('input').onchange=e=>{data.lesson.checks[p]=e.target.checked;data.lesson.progressUpdatedAt=new Date().toISOString();clearTimeout(lessonAdvanceTimer);save();renderLesson();renderSyncStatus();if(lessonParts.every(part=>data.lesson.checks[part])){const completed=data.lesson.number;lessonAdvanceTimer=setTimeout(()=>{if(!lessonParts.every(part=>data.lesson.checks[part]))return;data.lesson.number=completed+1;data.lesson.checks=Object.fromEntries(lessonParts.map(part=>[part,false]));data.lesson.progressUpdatedAt=new Date().toISOString();save();renderLesson(t('lessonAdvance',{from:completed,to:completed+1}));renderSyncStatus()},500)}};box.appendChild(l)});const n=lessonParts.filter(p=>data.lesson.checks[p]).length;document.querySelector('#lessonProgressBar').style.width=(n/lessonParts.length*100)+'%';let note=document.querySelector('#lessonAdvanceNote');if(!note){note=document.createElement('p');note.id='lessonAdvanceNote';note.className='lesson-advance-note';note.setAttribute('aria-live','polite');box.insertAdjacentElement('afterend',note)}note.textContent=message}
function renderWords(){const k=todayKey(),w=data.logs.words[k]||{new:0,review:0};document.querySelector('#newWordsDone').textContent=w.new;document.querySelector('#reviewWordsDone').textContent=w.review;document.querySelector('#newWordsGoal').textContent=data.settings.newWordsGoal;document.querySelector('#reviewWordsGoal').textContent=data.settings.reviewWordsGoal}
function weekKeys(){const d=new Date();const mon=new Date(d);const shift=(d.getDay()+6)%7;mon.setDate(d.getDate()-shift);return Array.from({length:7},(_,i)=>{const x=new Date(mon);x.setDate(mon.getDate()+i);return todayKey(x)})}
function renderListening(){const cats=[['本文リスニング',['本文リスニング','教材听力']],['泛聴',['泛聴','课外听力']],['精聴',['精聴','精听']],['シャドーイング',['シャドーイング','跟读']]];const totals=Object.fromEntries(cats.map(([c])=>[c,0]));weekKeys().forEach(k=>{const x=data.logs.listening[k]||{};cats.forEach(([label,keys])=>keys.forEach(key=>totals[label]+=Number(x[key]||0)))});document.querySelector('#listeningStats').innerHTML=cats.map(([c])=>`<div class="listen-stat"><span>${trText(c)}</span><strong>${totals[c]}</strong> ${t('minute')}</div>`).join('')}
function renderWeekend(){const card=document.querySelector('#weekendTestCard');card.style.display=isWeekend()?'flex':'none'}

let calDate=new Date(new Date().getFullYear(),new Date().getMonth(),1);
function renderCalendar(){const title=document.querySelector('#calendarTitle'),box=document.querySelector('#calendar');title.textContent=`${calDate.getFullYear()}年 ${calDate.getMonth()+1}月`;document.querySelectorAll('.weekdays span').forEach((el,i)=>el.textContent=lang()==='zh'?['一','二','三','四','五','六','日'][i]:['月','火','水','木','金','土','日'][i]);box.innerHTML='';const first=new Date(calDate.getFullYear(),calDate.getMonth(),1);const start=new Date(first);start.setDate(first.getDate()-((first.getDay()+6)%7));for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const k=todayKey(d),ts=tasksForDateKey(k),seconds=practiceSecondsForDate(k);const el=document.createElement('div');el.className='day';if(d.getMonth()!=calDate.getMonth())el.classList.add('other');if(k===todayKey())el.classList.add('today');if(ts.length&&ts.every(t=>t.done))el.classList.add('complete');else if(ts.some(t=>t.done))el.classList.add('partial');el.innerHTML=`<span class="day-number">${d.getDate()}</span><span class="day-study" data-study-date="${k}" ${seconds>0?'':'hidden'}>${formatStudyShort(seconds)}</span>`;el.setAttribute('aria-label',`${d.getMonth()+1}月${d.getDate()}日${seconds>0?'、'+formatStudyTotal(seconds):''}`);box.appendChild(el)}updateCalendarPracticeDisplay()}
function renderSummary(){const ts=currentWeekTasks();const done=ts.filter(t=>t.done).length;document.querySelector('#weekRate').textContent=(ts.length?Math.round(done/ts.length*100):0)+'%';document.querySelector('#masteredWords').textContent=data.vocab.filter(v=>v.mastery>=3).length}
function calcStreak(){let n=0,d=new Date();for(let i=0;i<365;i++){const k=todayKey(d),ts=tasksForDateKey(k);if(ts&&ts.some(t=>t.done)){n++;d.setDate(d.getDate()-1)}else if(i===0){d.setDate(d.getDate()-1)}else break}return n}
function openModal(html){const m=document.querySelector('#modal'),c=document.querySelector('#modalContent');c.innerHTML=html;if(!m.open)m.showModal();return c}
const modal=document.querySelector('#modal');modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}

document.querySelector('#logWordsBtn').onclick=()=>{const k=todayKey(),cur=data.logs.words[k]||{new:0,review:0};const c=openModal(`<h3>${t('wordsModalTitle')}</h3><div class="field"><label>${t('newWords')}</label><input id="nw" type="number" min="0" value="${cur.new}"></div><div class="field"><label>${t('reviewWords')}</label><input id="rw" type="number" min="0" value="${cur.review}"></div><div class="modal-actions"><button value="cancel" class="small-btn ghost">${t('cancel')}</button><button id="saveWords" value="default" class="small-btn">${t('save')}</button></div>`);c.querySelector('#saveWords').onclick=e=>{e.preventDefault();data.logs.words[k]={new:+c.querySelector('#nw').value||0,review:+c.querySelector('#rw').value||0};save();document.querySelector('#modal').close();renderWords();renderSyncStatus()}}
document.querySelector('#logListeningBtn').onclick=()=>{const c=openModal(`<h3>${t('listeningModalTitle')}</h3><div class="field"><label>${t('kind')}</label><select id="lc"><option value="本文リスニング">${trText('本文リスニング')}</option><option value="泛聴">${trText('泛聴')}</option><option value="精聴">${trText('精聴')}</option><option value="シャドーイング">${trText('シャドーイング')}</option></select></div><div class="field"><label>${t('minute')}</label><input id="lm" type="number" min="1" value="15"></div><div class="modal-actions"><button value="cancel" class="small-btn ghost">${t('cancel')}</button><button id="saveL" class="small-btn">${t('save')}</button></div>`);c.querySelector('#saveL').onclick=e=>{e.preventDefault();const k=todayKey(),cat=c.querySelector('#lc').value,min=+c.querySelector('#lm').value||0;data.logs.listening[k]=data.logs.listening[k]||{};data.logs.listening[k][cat]=(data.logs.listening[k][cat]||0)+min;save();document.querySelector('#modal').close();renderListening();renderSyncStatus()}}
document.querySelector('#editLessonBtn').onclick=()=>{const c=openModal(`<h3>${t('lessonModalTitle')}</h3><div class="field"><label>${t('currentLesson')}</label><input id="ln" type="number" min="1" value="${data.lesson.number}"></div><div class="modal-actions"><button value="cancel" class="small-btn ghost">${t('cancel')}</button><button id="saveLesson" class="small-btn">${t('save')}</button></div>`);c.querySelector('#saveLesson').onclick=e=>{e.preventDefault();data.lesson.number=+c.querySelector('#ln').value||1;data.lesson.checks=Object.fromEntries(lessonParts.map(x=>[x,false]));data.lesson.progressUpdatedAt=new Date().toISOString();save();document.querySelector('#modal').close();renderLesson();renderSyncStatus()}}
document.querySelector('#addTaskBtn').onclick=()=>{const c=openModal(`<h3>${t('addTaskTitle')}</h3><div class="field"><label>${t('taskLabel')}</label><input id="tt" placeholder="${t('taskPlaceholder')}"></div><div class="field"><label>${t('kind')}</label><select id="ty"><option value="教科書">${trText('教科書')}</option><option value="文法">${trText('文法')}</option><option value="リスニング">${trText('リスニング')}</option><option value="シャドーイング">${trText('シャドーイング')}</option><option value="復習">${trText('復習')}</option><option value="会話">${trText('会話')}</option></select></div><div class="modal-actions"><button value="cancel" class="small-btn ghost">${t('cancel')}</button><button id="saveT" class="small-btn">${t('add')}</button></div>`);c.querySelector('#saveT').onclick=e=>{e.preventDefault();const title=c.querySelector('#tt').value.trim();if(!title)return;currentWeekTasks().push(task('custom-'+Date.now(),title,c.querySelector('#ty').value,'追加タスク',dayIndex()));save();document.querySelector('#modal').close();render();renderSyncStatus()}}

document.querySelector('#vocabBtn').onclick=()=>showVocab();
function showVocab(){
 const rows=data.vocab.slice().sort((a,b)=>b.wrong-a.wrong).map(v=>`<div class="task-item"><div class="task-body"><div class="task-title">${esc(v.word)} <span class="muted">${esc(v.kana)}</span></div><div class="task-meta">${esc(v.meaning)} · ${t('mastery')} ${v.mastery}/3 · ${t('miss')} ${v.wrong}</div>${v.collocations?`<div class="task-meta">${t('collocation')}：${esc(v.collocations)}</div>`:''}</div><div class="vocab-actions"><button type="button" class="small-btn ghost" data-edit="${esc(v.id)}">${t('edit')}</button><button type="button" class="small-btn ghost vocab-delete" data-delete="${esc(v.id)}">${lang()==='zh'?'删除':'削除'}</button></div></div>`).join('');
 const empty=`<p class="muted">${t('emptyVocab')}</p>`;
 const c=openModal(`<h3>${t('vocabList')} <span class="muted">${data.vocab.length} ${t('wordCount')}</span></h3><button type="button" id="addV" class="small-btn">${t('addWord')}</button><div class="vocab-list">${rows||empty}</div><div class="modal-actions"><button class="small-btn ghost">${t('close')}</button></div>`);
 c.querySelector('#addV').onclick=()=>editVocab();
 c.querySelectorAll('[data-edit]').forEach(btn=>btn.onclick=()=>editVocab(btn.dataset.edit));
 c.querySelectorAll('[data-delete]').forEach(btn=>btn.onclick=()=>deleteVocab(btn.dataset.delete));
}
function editVocab(id){
 const existing=id?data.vocab.find(v=>v.id===id):null;
 const c=openModal(`<h3>${existing?t('editWord'):t('addWordTitle')}</h3><div class="field"><label>${t('japanese')}</label><input id="vw" value="${esc(existing?.word||'')}"></div><div class="field"><label>${t('kana')}</label><input id="vk" value="${esc(existing?.kana||'')}"></div><div class="field"><label>${t('meaning')}</label><input id="vm" value="${esc(existing?.meaning||'')}"></div><div class="field"><label>${t('collocation')}</label><input id="vc" value="${esc(existing?.collocations||'')}" placeholder="例：約束を守る"></div><p class="muted">${t('manualMeaning')}</p><div class="modal-actions"><button type="button" id="backV" class="small-btn ghost">${t('back')}</button><button id="saveV" class="small-btn">${t('save')}</button></div>`);
 c.querySelector('#backV').onclick=showVocab;
 c.querySelector('#saveV').onclick=e=>{e.preventDefault();const word=c.querySelector('#vw').value.trim(),kana=c.querySelector('#vk').value.trim(),meaning=c.querySelector('#vm').value.trim(),collocations=c.querySelector('#vc').value.trim();if(!word||!meaning){alert(t('needWordMeaning'));return}if(existing){Object.assign(existing,{word,kana,meaning,collocations})}else{data.vocab.push({id:'v'+Date.now(),word,kana,meaning,collocations,mastery:0,wrong:0,created:todayKey()})}save();showVocab();renderSyncStatus()};
}
function deleteVocab(id){const v=data.vocab.find(x=>x.id===id);if(!v||!confirm(t('deleteWord',{word:v.word})))return;data.vocab=data.vocab.filter(x=>x.id!==id);save();showVocab();renderSyncStatus()}

const testBtns=['#startTestBtn','#quickTestBtn'];testBtns.forEach(s=>document.querySelector(s).onclick=()=>startTest());
function startTest(){
 if(data.vocab.length<4){alert(t('testNeedVocab'));return}
 const pool=[...data.vocab].sort((a,b)=>(b.wrong-a.wrong)||Math.random()-.5).slice(0,Math.min(20,data.vocab.length));
 let idx=0,score=0,wrong=[];const modes=['日→中','中→日','听音辨词','语境'];
 function next(){if(idx>=pool.length)return finish();const v=pool[idx],mode=modes[idx%4];let html=`<h3>${t('testTitle')} <span class="muted">${idx+1}/${pool.length}</span></h3>`;
   if(mode==='日→中') html+=`<div class="test-q">${esc(v.word)} <span class="muted">${esc(v.kana)}</span></div><div class="field"><label>${t('answerMeaning')}</label><input id="ans" autocomplete="off"></div>`;
   if(mode==='中→日') html+=`<div class="test-q">${esc(v.meaning)}</div><div class="field"><label>${t('answerJapanese')}</label><input id="ans" autocomplete="off"></div>`;
   if(mode==='听音辨词') html+=`<div class="test-q">${t('listeningQuestion')}</div><button type="button" id="speak" class="small-btn ghost">${t('play')}</button><div class="field"><label>${t('heardWord')}</label><input id="ans" autocomplete="off"></div>`;
   if(mode==='语境') html+=`<div class="test-q">${t('contextQuestion',{meaning:esc(v.meaning)})}</div><div class="field"><label>${t('answer')}</label><input id="ans" autocomplete="off"></div>`;
   html+=`<div class="modal-actions"><button type="button" id="submitA" class="small-btn">${t('submit')}</button></div>`;
   const c=openModal(html);if(mode==='听音辨词'){c.querySelector('#speak').onclick=()=>speakJP(v.word);setTimeout(()=>speakJP(v.word),250)}
   c.querySelector('#submitA').onclick=()=>{const a=c.querySelector('#ans').value.trim().toLowerCase();let ok=false;if(mode==='日→中')ok=v.meaning.split(/[；;,，]/).some(x=>a.includes(x.trim().toLowerCase())||x.trim().toLowerCase().includes(a));else ok=[v.word,v.kana].map(x=>x.toLowerCase()).includes(a);if(ok){score++;v.mastery=Math.min(3,v.mastery+1)}else{v.wrong++;v.mastery=Math.max(0,v.mastery-1);wrong.push(v)}idx++;save();next()}
 }
 function finish(){const pct=Math.round(score/pool.length*100);data.logs.tests[todayKey()]={score,total:pool.length,pct,wrong:wrong.map(v=>v.id)};save();const c=openModal(`<h3>${t('testDone')}</h3><p class="${pct>=80?'result-good':'result-bad'}" style="font-size:34px;margin:10px 0">${score}/${pool.length} · ${pct}%</p><p>${t('wrongSummary',{count:wrong.length})}</p>${wrong.length?'<p class="muted">'+wrong.map(v=>esc(v.word)).join('、')+'</p>':''}<div class="modal-actions"><button class="small-btn">${t('done')}</button></div>`);const tsk=currentWeekTasks().find(x=>x.type==='テスト'&&!x.done);if(tsk)tsk.done=true;save();render()}
 next();
}
function speakJP(text){if(!('speechSynthesis'in window))return alert(t('speechUnsupported'));speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ja-JP';u.rate=.85;speechSynthesis.speak(u)}

document.querySelector('#prevMonthBtn').onclick=()=>{calDate.setMonth(calDate.getMonth()-1);renderCalendar()};document.querySelector('#nextMonthBtn').onclick=()=>{calDate.setMonth(calDate.getMonth()+1);renderCalendar()};
document.querySelector('[data-scroll="calendar"]').onclick=()=>document.querySelector('#calendar').scrollIntoView({behavior:'smooth',block:'center'});document.querySelector('[data-scroll="top"]').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});

document.querySelector('#settingsBtn').onclick=()=>{const c=openModal(`<h3>${t('settingsTitle')}</h3><div class="field"><label>${t('newWordsGoal')}</label><input id="sg1" type="number" min="1" value="${data.settings.newWordsGoal}"></div><div class="field"><label>${t('reviewWordsGoal')}</label><input id="sg2" type="number" min="1" value="${data.settings.reviewWordsGoal}"></div><div class="field"><label>${t('weekdayCap')}</label><input id="cap" type="number" min="30" value="${data.settings.weekdayCap}"></div><div class="field"><label>${lang()==='zh'?'界面语言':'表示言語'}</label><select id="uiLang"><option value="ja" ${lang()==='ja'?'selected':''}>日本語</option><option value="zh" ${lang()==='zh'?'selected':''}>中文</option></select></div><div class="modal-actions"><button value="cancel" class="small-btn ghost">${t('cancel')}</button><button id="saveS" class="small-btn">${t('save')}</button></div>`);c.querySelector('#saveS').onclick=e=>{e.preventDefault();data.settings.newWordsGoal=+c.querySelector('#sg1').value||10;data.settings.reviewWordsGoal=+c.querySelector('#sg2').value||10;data.settings.weekdayCap=+c.querySelector('#cap').value||70;data.settings.language=c.querySelector('#uiLang').value==='zh'?'zh':'ja';save();document.querySelector('#modal').close();render()}}

document.querySelector('#syncBtn').onclick=()=>{const s=sync.state;const configured=s.available;const user=s.user;const err=s.error?`<p class="sync-error">${esc(s.error.message||s.error)}</p>`:'';const html=user?`<h3>${t('syncTitle')}</h3><p class="muted">${esc(user.email||t('loggedIn'))}</p><p>${esc(syncMessage(s.message))}</p>${err}<div class="field"><label>${t('phonePassword')}</label><input id="newPassword" type="password" autocomplete="new-password" minlength="6" placeholder="${t('passwordPlaceholder')}"></div><div class="button-row"><button type="button" id="syncNow" class="small-btn">${t('syncNow')}</button><button type="button" id="setPassword" class="small-btn ghost">${t('setPassword')}</button><button type="button" id="logout" class="small-btn ghost">${t('logout')}</button></div><div class="modal-actions"><button class="small-btn ghost">${t('close')}</button></div>`:`<h3>${t('syncTitle')}</h3><p>${configured?t('syncIntro'):t('syncUnconfigured')}</p>${err}${configured?`<div class="field"><label>${t('email')}</label><input id="email" type="email" autocomplete="email" placeholder="you@example.com"></div><div class="field"><label>${t('password')}</label><input id="password" type="password" autocomplete="current-password" minlength="6" placeholder="${t('passwordPlaceholder')}"></div><div class="button-row"><button type="button" id="passwordLogin" class="small-btn">${t('login')}</button><button type="button" id="passwordSignup" class="small-btn ghost">${t('signup')}</button></div><div class="modal-actions"><button value="cancel" class="small-btn ghost">${t('close')}</button><button type="button" id="sendLogin" class="small-btn ghost">${t('emailLink')}</button></div>`:`<div class="modal-actions"><button class="small-btn ghost">${t('close')}</button></div>`}`;const c=openModal(html);const emailValue=()=>c.querySelector('#email').value.trim();const passwordValue=()=>c.querySelector('#password').value;const login=c.querySelector('#passwordLogin');if(login)login.onclick=async()=>{const email=emailValue(),password=passwordValue();if(!email||!password)return alert(t('needEmailPassword'));try{await sync.signInPassword(email,password);alert(t('loginOk'));document.querySelector('#modal').close();render()}catch(err){alert(err.message||t('loginFail'))}};const signup=c.querySelector('#passwordSignup');if(signup)signup.onclick=async()=>{const email=emailValue(),password=passwordValue();if(!email||password.length<6)return alert(t('needSignup'));try{await sync.signUpPassword(email,password);alert(t('signupOk'));document.querySelector('#modal').close();render()}catch(err){alert(err.message||t('signupFail'))}};const setPassword=c.querySelector('#setPassword');if(setPassword)setPassword.onclick=async()=>{const password=c.querySelector('#newPassword').value;if(password.length<6)return alert(t('needPassword'));try{await sync.updatePassword(password);alert(t('passwordOk'))}catch(err){alert(err.message||t('passwordFail'))}};const send=c.querySelector('#sendLogin');if(send)send.onclick=async()=>{const email=emailValue();if(!email)return alert(t('needEmail'));try{await sync.signIn(email);alert(t('mailOk'))}catch(err){alert(err.message||t('mailFail'))}};const syncNow=c.querySelector('#syncNow');if(syncNow)syncNow.onclick=()=>sync.pullThenPush();const logout=c.querySelector('#logout');if(logout)logout.onclick=()=>sync.signOut()};

document.querySelector('#backupBtn').onclick=()=>showBackup()
function showBackup(){const backups=listLocalBackups();const backupHtml=backups.length?`<div class="restore-list"><p class="muted">${t('backupCount',{count:backups.length})}</p>${backups.map((b,i)=>`<div class="restore-item"><div><strong>${t('deviceBackup',{num:i+1})}</strong><div class="task-meta">${esc(b.time||t('unknownTime'))} · ${t('dataAmount')} ${b.score}</div></div><div class="restore-actions"><button type="button" class="small-btn ghost" data-preview-backup="${esc(b.key)}">${t('preview')}</button><button type="button" class="small-btn" data-restore-backup="${esc(b.key)}">${t('restore')}</button></div></div>`).join('')}</div>`:'';const c=openModal(`<h3>${t('backupTitle')}</h3><p>${t('backupIntro')}</p><div class="button-row"><button type="button" id="export" class="small-btn">${t('export')}</button><button type="button" id="import" class="small-btn ghost">${t('import')}</button></div>${backupHtml}<div class="modal-actions"><button class="small-btn ghost">${t('close')}</button></div>`);c.querySelector('#export').onclick=exportData;c.querySelector('#import').onclick=()=>document.querySelector('#importInput').click();c.querySelectorAll('[data-preview-backup]').forEach(btn=>btn.onclick=()=>previewLocalBackup(btn.dataset.previewBackup));c.querySelectorAll('[data-restore-backup]').forEach(btn=>btn.onclick=()=>restoreLocalBackup(btn.dataset.restoreBackup))}
function previewLocalBackup(key){try{const value=normalizeData(JSON.parse(localStorage.getItem(key)||'{}'));alert(t('backupPreview',{lesson:value.lesson.number||1,vocab:(value.vocab||[]).length,weeks:Object.keys(value.weekPlans||{}).length,listening:Object.keys(value.logs?.listening||{}).length,tests:Object.keys(value.logs?.tests||{}).length}))}catch{alert(t('backupUnreadable'))}}
function restoreLocalBackup(key){try{const value=normalizeData(JSON.parse(localStorage.getItem(key)||'{}'));if(!confirm(t('restoreConfirm')))return;makeLocalBackup('before-manual-restore');replaceData(value,{skipRender:true});save();document.querySelector('#modal').close();render();alert(t('restoreOk'))}catch{alert(t('restoreFail'))}}
function exportData(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`日本語ノート-backup-${todayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
document.querySelector('#importInput').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{replaceData(JSON.parse(r.result),{skipRender:true});save();render();alert(t('importOk'))}catch{alert(t('importFail'))}};r.readAsText(f)}

